#!/usr/bin/env python3
# Proof-of-Concept: Keystream Reuse Privacy Attack in SSH SDCTR Mode
# RFC 4344 Section 6.1 describes that encrypting >2^L blocks with the same key
# in SDCTR mode causes keystream reuse, enabling plaintext recovery via XOR.

import struct
import os
from Crypto.Cipher import AES
from Crypto.Util.number import bytes_to_long, long_to_bytes

# Constants
BLOCK_SIZE = 16  # AES block size in bytes (128 bits)
L = 128          # Block cipher length in bits
MAX_BLOCKS = 2 ** (L // 8)  # 2^16 blocks for AES-128

# Simulate a vulnerable SSH server that does not rekey
class VulnerableSSHServer:
    def __init__(self, key):
        self.key = key
        self.counter = 0
        self.cipher = AES.new(key, AES.MODE_ECB)  # SDCTR uses ECB internally

    def encrypt_packet(self, plaintext):
        # SDCTR mode: encrypt counter to generate keystream, XOR with plaintext
        ciphertext = b''
        for i in range(0, len(plaintext), BLOCK_SIZE):
            block = plaintext[i:i+BLOCK_SIZE]
            if len(block) < BLOCK_SIZE:
                block = block + b'\x00' * (BLOCK_SIZE - len(block))  # Pad to block size
            
            # Generate keystream block by encrypting the counter
            counter_block = struct.pack('>Q', self.counter) + b'\x00' * 8  # 64-bit counter
            keystream_block = self.cipher.encrypt(counter_block)
            
            # XOR plaintext with keystream
            encrypted_block = bytes(a ^ b for a, b in zip(block, keystream_block))
            ciphertext += encrypted_block
            
            self.counter += 1
            if self.counter >= MAX_BLOCKS:
                # Vulnerable implementation does not rekey, causing keystream reuse
                self.counter = 0  # Wrap around counter
        
        return ciphertext

# Attacker function to exploit keystream reuse
def exploit_keystream_reuse(ciphertext1, ciphertext2, known_plaintext1):
    # XOR two ciphertexts to cancel out the reused keystream
    xored = bytes(a ^ b for a, b in zip(ciphertext1, ciphertext2))
    
    # XOR with known plaintext to recover the other plaintext
    recovered_plaintext2 = bytes(a ^ b for a, b in zip(xored, known_plaintext1))
    return recovered_plaintext2

# Main demonstration
def main():
    # Generate a random key
    key = os.urandom(16)
    
    # Create vulnerable server instance
    server = VulnerableSSHServer(key)
    
    # Prepare two different plaintexts
    plaintext1 = b'Hello, this is the first secret message!'
    plaintext2 = b'And this is the second secret message!'
    
    # Encrypt both plaintexts (simulating >2^L blocks encrypted with same key)
    ciphertext1 = server.encrypt_packet(plaintext1)
    ciphertext2 = server.encrypt_packet(plaintext2)
    
    # Attacker observes ciphertexts and knows one plaintext
    recovered_plaintext2 = exploit_keystream_reuse(ciphertext1, ciphertext2, plaintext1)
    
    # Output results
    print(f"Original Plaintext 1: {plaintext1.decode()}")
    print(f"Original Plaintext 2: {plaintext2.decode()}")
    print(f"Recovered Plaintext 2: {recovered_plaintext2.decode()}")
    
    # Verify recovery
    if recovered_plaintext2 == plaintext2:
        print("\n[+] SUCCESS: Plaintext recovered due to keystream reuse!")
    else:
        print("\n[-] FAILURE: Plaintext recovery failed.")

if __name__ == "__main__":
    main()